head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst50000";
scwin.timer = undefined;
scwin.time_slideshow4 = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.time_slideshow4 = ""; scwin.time_slideshow5 = "";
        scwin.init_nowVars();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_disclosure();
        scwin.init_disclosure_proc();
        scwin.init_schedule();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst50000.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — svrGubun, index, isExaService

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "a_44", attr: "src", fn: function () { return "http://" + String((dma_pageContext.get("hostName") ?? "")) + "/"; } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_3", fn: function(){ return ((dma_pageContext.get("svrGubun") ?? "") === 'dev'); } }, { id: "c_when_5", fn: function(){ return ((dma_pageContext.get("svrGubun") ?? "") === 'test1'); } }, { id: "c_when_7", fn: function(){ return ((dma_pageContext.get("svrGubun") ?? "") === 'test2'); } }, { id: "c_when_9", fn: function(){ return ((dma_pageContext.get("svrGubun") ?? "") === 'real1'); } }, { id: "c_when_11", fn: function(){ return ((dma_pageContext.get("svrGubun") ?? "") === 'real2'); } }, { id: "c_when_13", fn: function(){ return ((dma_pageContext.get("svrGubun") ?? "") === 'dr1'); } }, { id: "c_when_15", fn: function(){ return ((dma_pageContext.get("svrGubun") ?? "") === 'dr2'); } }, { id: "c_otherwise_17", fn: function(){ return (!(((dma_pageContext.get("svrGubun") ?? "") === 'dev') || ((dma_pageContext.get("svrGubun") ?? "") === 'test1') || ((dma_pageContext.get("svrGubun") ?? "") === 'test2') || ((dma_pageContext.get("svrGubun") ?? "") === 'real1') || ((dma_pageContext.get("svrGubun") ?? "") === 'real2') || ((dma_pageContext.get("svrGubun") ?? "") === 'dr1') || ((dma_pageContext.get("svrGubun") ?? "") === 'dr2'))); } }, { id: "c_when_98", fn: function(){ return (!(String(((dma_pageContext.get("index") ?? "")) == null ? '' : ((dma_pageContext.get("index") ?? ""))).length === 0)); } }, { id: "c_otherwise_105", fn: function(){ return (!((!(String(((dma_pageContext.get("index") ?? "")) == null ? '' : ((dma_pageContext.get("index") ?? ""))).length === 0)))); } }, { id: "if_svrGubun", fn: function(){ return ((dma_pageContext.get("svrGubun") ?? "") !== 'dr' && (dma_pageContext.get("isExaService") ?? "") ==='Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_99", entity: "dlt_index", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("idxIndEngNm")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("clsprcIdx")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("updownIdx")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_scrnmode", fn: function () { return String(String((dma_pageContext.get("scrnmode") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    $('input').placeholder();
};

/**
 * @method
 * @name init_disclosure
 * @description 초기화 — disclosure
 * @returns {void}
 * @hidden N
 */
scwin.init_disclosure = function () {
    $("div.temp-contents").empty();
    if ("0" === "0") {
        $("div.temp-contents").load('/external/dst/main/main_contents.htm?_=' + new Date().getTime(), function() {
                scwin.init_disclosure_proc();
        });
    } else {
        if ("0" === "1") {
            $('div.temp-contents').load(scwin.getMainbatchUrl("today"), function() {
                    scwin.init_disclosure_proc();
            });
        }
    }
};

/**
 * @method
 * @name init_disclosure_proc
 * @description 초기화 — disclosure proc
 * @returns {void}
 * @hidden N
 */
scwin.init_disclosure_proc = function () {
    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    $("section.main-important #main-today-all article").html($("div.temp-contents #main-today-all article").html());
    $("section.main-important #main-today-stockmkt article").html($("div.temp-contents #main-today-stockmkt article").html());
    $("section.main-important #main-today-kosdaqmkt article").html($("div.temp-contents #main-today-kosdaqmkt article").html());
    $("section.main-important #main-today-konexmkt article").html($("div.temp-contents #main-today-konexmkt article").html());
    $("section.main-important #main-today-drvclss article").html($("div.temp-contents #main-today-drvclss article").html());
    (console.error('[sdd] 이 화면 문서에 #currentDateTime 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#currentDateTime")).html(scwin.getCurrentDateTime());
    scwin.mainImportant_init();
};

/**
 * @method
 * @name init_schedule
 * @description 초기화 — schedule
 * @returns {void}
 * @hidden N
 */
scwin.init_schedule = function () {
    $("section.schedule article.ir ul").empty();
    $("section.schedule article.ir ul").load('/main.do?method=searchIRSchedule');
    $("section.schedule article.stock ul").empty();
    $("section.schedule article.stock ul").load('/main.do?method=searchStockSchedule');
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $('section.news_spot article.stockindex ul').simple_slideshow5({ interval: 2500, btn: "section.news_spot article.stockindex h3.ttl a" });
        const detail_search_opt = { btn: "header.container section.search a.more", close: "a.btn-pop-close", handle: "hgroup.handle", e: "click" };
        $('section.detail_search.popup').dim_dialog(detail_search_opt);
        bt_util_init();
        scwin.gnb_init();
        if ("0" === "0") {
            $('section.main-important').load('/external/dst/main/main_contents.htm?_=' + new Date().getTime(), function(response, status, xhr) {
                    if (status === "error") {
                        scwin.loadJSP();
                    } else {
                        scwin.loadBatch();
                    }
                    if ($c.util.getComponent('ipt_scrnmode').getValue() === "3") {
                        $(".today.wrapper").removeClass("active");
                        $(".market.wrapper").removeClass("active");
                        $(".valueup.wrapper").addClass("active");
                        $(".ipo.wrapper").removeClass("active");
                        $(".bond.wrapper").removeClass("active");
                    } else {
                        $(".today.wrapper").addClass("active");
                        $(".market.wrapper").removeClass("active");
                        $(".valueup.wrapper").removeClass("active");
                        $(".ipo.wrapper").removeClass("active");
                        $(".bond.wrapper").removeClass("active");
                    }
            });
        } else {
            if ("0" === "1") {
                scwin.loadJSP();
            }
        }
        scwin.fnStart();
        scwin.fnBookmark();
        scwin.init_schedule();
        scwin.init();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst50000.onpageload' }); }
};

// [A] 초기 목록 미해결 — jlddst50000: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

