/**
 * @method
 * @name mainImportant_init
 * @description main Important init 처리
 * @returns {void}
 * @hidden N
 */
scwin.mainImportant_init = function () {
    $('section.main-important a.bm').bind("mouseover focus", function() {
            $('section.main-important section.wrapper').removeClass("active");
            let oc = $(this).attr("class");
            oc = oc.replace(" bm", "");
            $('section.main-important section.' + oc + ".wrapper").addClass("active");
    });
    $('section.main-important a.bm').bind("click", function() {
            return false;
    });
    $('section.main-important a.mm').bind("mouseover focus", function() {
            $(this).parent().parent().children("li").removeClass("active");
            $(this).parent().addClass("active");
    });
    $('section.main-important a.mm').bind("click", function() {
            return false;
    });
};

/**
 * @method
 * @name fnBookmark
 * @description fn Bookmark 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnBookmark = function () {
    const cookieName = "krxComp";
    const cookies = $c.util.getSessionStorage(cookieName);
    if (cookies != null) {
        (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).removeAll ? ($c.util.getComponent('txt_myBookmark')).removeAll() : (($c.util.getComponent('txt_myBookmark')) && ($c.util.getComponent('txt_myBookmark')).setValue ? ($c.util.getComponent('txt_myBookmark')).setValue('') : void 0));
        const items = cookies.split("/");
        let max = 0;
        for (i in items) {
            if (max === 10) {
                break;
            }
            const item = items[i].split(",");
            const repIsuSrtCd = item[1];
            const corpNameEnc = encodeURIComponent(item[2]);
            const corpName = item[2];
            const isurcd = item[3];
            if (undefined !== corpName && undefined !== isurcd) {
                const url = "/disclosureSimpleSearch.do?method=disclosureSimpleSearchMain&repIsuSrtCd=" + repIsuSrtCd + "&isurCd=" + isurcd + "&searchCorpName=" + corpNameEnc;
                $("#txt_myBookmark").append("<a href=\"" + url + "\" title=\"" + corpName + " 검색\">" + corpName + "</a> ");
            }
            max++;
        }
        const myBookmarkList = $("#txt_myBookmark").children("a");
        let bookmarkWidth = 10;
        if (myBookmarkList.length <= 1) {
            bookmarkWidth = 700;
        }
        for (let i = 0; i < myBookmarkList.length; i++) {
            bookmarkWidth = bookmarkWidth + myBookmarkList[i].offsetWidth + 10;
        }
        $("#txt_myBookmark")[0].style.width = bookmarkWidth + "px";
    }
};

/**
 * @method
 * @name getCurrentDateTime
 * @description get Current Date Time 처리
 * @returns {void}
 * @hidden N
 */
scwin.getCurrentDateTime = function () {
    const d = new Date();
    const s = scwin.leadingZeros(d.getFullYear(), 4) + '-' + scwin.leadingZeros(d.getMonth() + 1, 2) + '-' + scwin.leadingZeros(d.getDate(), 2) + ' ' + scwin.leadingZeros(d.getHours(), 2) + ':' + scwin.leadingZeros(d.getMinutes(), 2) + ':' + scwin.leadingZeros(d.getSeconds(), 2);
    return s;
};

/**
 * @method
 * @name leadingZeros
 * @description leading Zeros 처리
 * @param {Number} n n
 * @param {*} digits digits
 * @returns {void}
 * @hidden N
 */
scwin.leadingZeros = function (n, digits) {
    let zero = '';
    n = n.toString();
    if (n.length < digits) {
        for (i = 0; i < digits - n.length; i++) {
            zero += '0';
        }
    }
    return zero + n;
};

