/**
 * @method
 * @name fnTopNoticeOpen
 * @description fn Top Notice Open 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnTopNoticeOpen = async function () {
    if (nCnt === 0) {
        await $c.win.alert("표시할 공지사항이 없습니다.");
        return;
    }
    $('section#topnotice article.ctt li:first').addClass("first");
    const style = $('#topnotice').attr("style");
    let bgpy = $('#topnotice').height() + "px";
    if (style.search("block") > 0) {
        bgpy = "0px";
    }
    setTimeout(function() {
            $('#topnotice').slideToggle(200);
            $("body").animate({ 'background-position-y': bgpy }, 200);
            if (nCnt > 1) {
                const slider_notice = $('.bxslider-notice').bxSlider({ mode: "fade", auto: true, speed: 200, autoControls: true });
            }
        }, 200);
};

/**
 * @method
 * @name activeImgName
 * @description active Img Name 처리
 * @param {*} src src
 * @returns {void}
 * @hidden N
 */
scwin.activeImgName = function (src) {
    const data = {  };
    const hover_str = "_active";
    const tmp = src.split("/");
    const ext = /^.+\.([^.]+)$/.exec(tmp[3]);
    data.filename = tmp[3].replace("." + ext[1], "");
    data.rov_filename = data.filename + hover_str + "." + ext[1];
    data.filename = data.filename + "." + ext[1];
    return data;
};
